/* harmony default export */ var ProductInterestCalculatorvue_type_script_lang_js = ({
  name: 'ProductInterestCalculator',
  emits: ['calculated'],
  props: {
    title: {
      type: String,
      default: '금리 미리 계산해보기'
    },
    annualRate: {
      type: Number,
      default: 0.028
    },
    initialAmount: {
      type: [String, Number],
      default: ''
    },
    initialMonths: {
      type: [String, Number],
      default: ''
    },
    initialPretaxAmount: {
      type: Number,
      default: 1040500
    },
    amountInputId: {
      type: String,
      default: 'tt1'
    },
    monthsInputId: {
      type: String,
      default: 'tt2'
    }
  },
  data() {
    return {
      isOpen: false,
      amount: String(this.initialAmount ?? ''),
      months: String(this.initialMonths ?? ''),
      pretaxAmount: this.initialPretaxAmount
    };
  },
  computed: {
    formattedPretaxAmount() {
      const value = Number(this.pretaxAmount) || 0;
      return `${value.toLocaleString('ko-KR')}원`;
    }
  },
  methods: {
    togglePanel() {
      this.isOpen = !this.isOpen;
    },
    calculate() {
      const principal = Number(String(this.amount).replace(/,/g, ''));
      const monthCount = Number(this.months);
      if (!principal || !monthCount) {
        this.pretaxAmount = 0;
        this.$emit('calculated', {
          principal: 0,
          months: 0,
          annualRate: this.annualRate,
          pretaxAmount: 0
        });
        return;
      }
      const yearFraction = monthCount / 12;
      this.pretaxAmount = Math.round(principal + principal * this.annualRate * yearFraction);
      this.$emit('calculated', {
        principal,
        months: monthCount,
        annualRate: this.annualRate,
        pretaxAmount: this.pretaxAmount
      });
    }
  }
});
